import json,re,html,hashlib,xml.etree.ElementTree as ET
from pathlib import Path
s=json.load(open('source.json')); a=json.load(open('answer.json')); r=json.load(open('reference-targets.json')); snap=json.load(open('reference-review-snapshot.json'))
assert len(a)==len(s)==12
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
classes={'material_reduction','coordination_only','retained_necessary','financing_transfer','payment_timing_relief','mixed','reserved','editorial_only'}
kinds={'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
units={'percent','euro','legal_duty','regime','calendar_days','working_days','financing','other'}
strip=lambda x:html.unescape(re.sub(r'<["'^>]+>'"','',x))
norm=lambda x:re.sub(r'\\s+',' ',x).strip()
for x,y in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']: assert x[k]==y[k],(x['number'],k)
 imp=y['substantive_impact']; assert imp['version']==1 and imp['classification'] in classes
 for k in ['assessment','scope_limitations','new_burdens_review']:assert len(imp[k])>=40,(x['number'],k)
 if y['status']=='retained_unchanged':
  assert y['proposed_xml'] is None and imp['classification']=='retained_necessary' and imp['effects']==[]
 else:
  assert y['status']=='rewrite_draft' and isinstance(y['proposed_xml'],str)
  tree=ET.fromstring('<root>'+y['proposed_xml']+'</root>')
  for e in list(tree.iter())[1:]:
   assert e.tag in allowed,(x['number'],e.tag)
   for k,v in e.attrib.items():assert k in {'rowspan','colspan'} and v.isdigit()
 if x['benefit_check_required']:assert len(y.get('benefit_review',''))>=100
 if y.get('change_type')=='normative_reduction':
  assert y['reform_policy_id']=='editorial_direction_2026_10_19'
  assert y['removed_provisions'] and all(len(v)>=30 for v in y['removed_provisions'])
 for effect in imp['effects']:
  assert set(effect)=={'kind','measure_id','description','before','after','unit','affected_population','conditions_and_transition','replacement_or_new_burdens','source_quote','proposed_quote'}
  assert effect['kind'] in kinds and effect['unit'] in units
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',effect['measure_id']) and 6<=len(effect['measure_id'])<=96
  for q,f in [('source_quote',x['source_xml']),('proposed_quote',y['proposed_xml'])]:
   assert len(effect[q])>=12 and norm(effect[q]) in norm(strip(f)),(x['number'],q,effect[q])
 key=x['code_id']+'|'+x['source_id']
 assert {c['target_key'] for c in y['reference_checks']}==set(r['requirements'][key])
 assert len(y['reference_checks'])==len(r['requirements'][key])
 for c in y['reference_checks']:
  assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256'] and len(c['assessment'])>=80
 print(y['number'],y['status'],imp['classification'],len(imp['effects']),'effets',len(y['reference_checks']),'renvois')
assert hashlib.sha256(Path('reference-targets.json').read_bytes()).hexdigest()==snap['reference_file_sha256']
print('JSON, identifiants, citations, balises, transitions déclarées et 53 empreintes : contrôles documentaires passés.')
PY"

